mapper.select:
select l.id, l.source, l.inquiry_type as inquiryType, l.name, l.contact_channel as contactChannel, l.contact_value as contactValue, l.message, l.status, l.handler_sys_user_id as handlerSysUserId, l.handler_note as handlerNote, l.handled_at as handledAt, l.created_at as createdAt, l.updated_at as updatedAt, su.user_name as handlerUserName, su.nick_name as handlerNickName from cm_contact_leads l left join sys_user su on su.user_id = l.handler_sys_user_id where 1 = 1
and ( l.id like concat('%', #{keyword}, '%') or l.name like concat('%', #{keyword}, '%') or l.contact_value like concat('%', #{keyword}, '%') or l.message like concat('%', #{keyword}, '%') or l.handler_note like concat('%', #{keyword}, '%') )
and l.inquiry_type = #{inquiryType}
and l.contact_channel = #{contactChannel}
and l.status = #{status}
order by case when l.status = 'new' then 0 when l.status = 'processing' then 1 else 2 end, l.created_at desc, l.id desc
